export const MONUMENTS = JSON.parse("[{\"id\":\"n1304505146\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"М. Е. Салтыкову-Щедрину\",\"x\":-168.8,\"z\":-148.7,\"subject\":\"Q211785\",\"inscription\":\"В этом доме с 1876 г. жил и в 1889 г. умер Михаил Евграфович Салтыков-Щедрин\"},{\"id\":\"n1304505175\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Дом Н. Д. Гурьева\",\"x\":-170.9,\"z\":-141.9,\"inscription\":\"Памятник архитектуры. Дом Н.Д. Гурьева (Э.Д. Нарышкина). Построен в первой трети XIX в., перестроен в 1843, 1856-1858 гг. Архитектор Г.Э. Боссе. Охраняется государством.\"},{\"id\":\"n1450164801\",\"kind\":\"memorial\",\"sub\":\"statue\",\"name\":\"И. С. Тургенев\",\"x\":-696.8,\"z\":-427.6,\"h\":4.5,\"startDate\":\"2001-08-14\",\"subject\":\"Q42831\",\"artist\":\"Ян Нейман, В. Свешников\"},{\"id\":\"n3511128450\",\"kind\":\"memorial\",\"sub\":\"bust\",\"name\":\"Карл Росси\",\"x\":-583,\"z\":-372.6,\"subject\":\"Q619584\"},{\"id\":\"n3511128451\",\"kind\":\"memorial\",\"sub\":\"bust\",\"name\":\"Джакомо Кваренги\",\"x\":-571.2,\"z\":-382.3,\"subject\":\"Q128623\"},{\"id\":\"n3511128452\",\"kind\":\"memorial\",\"sub\":\"bust\",\"name\":\"Антонио Ринальди\",\"x\":-573.3,\"z\":-397.4,\"subject\":\"Q19165\"},{\"id\":\"n3511128454\",\"kind\":\"memorial\",\"sub\":\"bust\",\"name\":\"Бартоломео Растрелли\",\"x\":-585.2,\"z\":-403.6,\"subject\":\"Q299687\"},{\"id\":\"n6285038595\",\"kind\":\"artwork\",\"x\":-666.8,\"z\":-202.1},{\"id\":\"n8777431238\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. Г. Белинскому\",\"x\":-386.5,\"z\":-150.9,\"subject\":\"Q192885\",\"inscription\":\"В этом доме в 1842-1846 г.г. жил Виссарион Григорьевич Белинский\"},{\"id\":\"n8777433430\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Л. Н. Толстому\",\"x\":-377.6,\"z\":-194.8,\"subject\":\"Q7243\",\"inscription\":\"В этом доме с 19 ноября 1855 года по 1 января 1856 года жил великий русский писатель Лев Николаевич Толстой\"},{\"id\":\"n8807524802\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"К. Н. Батюшкову\",\"x\":-465,\"z\":-194.1,\"subject\":\"Q471718\",\"inscription\":\"В этом доме в 1814-1815 и в 1824 годах жил и работал поэт Константин Николаевич Батюшков\"},{\"id\":\"n8901842644\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. И. Ленину\",\"x\":-663.9,\"z\":-415.1,\"subject\":\"Q1394\",\"inscription\":\"Здесь, в бывшем манеже, 15 апреля 1917 года на митинге солдат броневого дивизиона, 1 января 1918 года на собрании сводного отряда красногвардейцев, отправлявшихся на Западный фронт, выступал Владимир Ильич Ленин\"},{\"id\":\"n8954918606\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Издательству «Вперед»\",\"x\":-573.3,\"z\":-212.8,\"inscription\":\"В этом доме в 1906–1907 годах находилось большевистское издательство «Вперед». Редакционный совет издательства возглавлял В. И. Ленин. Он часто работал здесь и встречался с товарищами. В марте 1906 года в помещении издательства Ленин провел совещание ...\"},{\"id\":\"n7025578620\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Н. П. Акимову\",\"x\":-735.5,\"z\":-193.2,\"subject\":\"Q1185061\",\"inscription\":\"Здесь в 1935–1939 и 1956–1968 годах работал выдающийся режиссёр и художник Николай Павлович Акимов\"},{\"id\":\"n14109137033\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Г. Тукаю\",\"x\":-1607,\"z\":-121.9},{\"id\":\"n5228633808\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Г. В. Плеханову\",\"x\":-853.8,\"z\":-140.5,\"subject\":\"Q182905;Q2414103\",\"inscription\":\"В этом здании в читальных залах публичной библиотеки в 1874-1880 г.г. работал Г. В. Плеханов — основатель первой русской марксистской организации — группы «Освобождение труда»\"},{\"id\":\"n5507295907\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Сооружению здания для казённой библиотеки\",\"x\":-887,\"z\":-179.4,\"inscription\":\"По высочайше апробованному 1795 года Мая 16 дня плану повелено соорудить здание для Казенной Библиотеки\"},{\"id\":\"n5507566672\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"И. А. Крылову\",\"x\":-858.4,\"z\":-122.4,\"subject\":\"Q191480\",\"inscription\":\"В этом здании с 1812 г. по 1841 г. работал библиотекарем великий русский баснописец Иван Андреевич Крылов\"},{\"id\":\"n5507566674\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. И. Ленину\",\"x\":-865,\"z\":-175.1,\"subject\":\"Q1394\",\"inscription\":\"В. И. Ленин был постоянным читателем Публичной Библиотеки в 1893–1895 г.г.\"},{\"id\":\"n6553571327\",\"kind\":\"artwork\",\"sub\":\"plaque\",\"name\":\"В. И. Ленину\",\"x\":-1975.7,\"z\":-121.7,\"subject\":\"Q1394\",\"inscription\":\"Здесь, в бывшем здании Народного комиссариата по военным делам, 17 и 22 декабря 1917 года В. И. Ленин провел совещания, на которых были выработаны основные положения создания Рабоче-Крестьянской Красной Армии\"},{\"id\":\"n4898059106\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"С. А. Есенину\",\"x\":-2374.7,\"z\":-176.3,\"subject\":\"Q31628\",\"inscription\":\"В бывшей гостинице «Англетер» 28 декабря 1925 года трагически оборвалась жизнь поэта Сергея Есенина\"},{\"id\":\"n14115336542\",\"kind\":\"memorial\",\"sub\":\"bust\",\"name\":\"О. Монферрану\",\"x\":-2555.6,\"z\":-169.9},{\"id\":\"n14135508013\",\"kind\":\"artwork\",\"sub\":\"street_art\",\"x\":-2431.2,\"z\":-120.9},{\"id\":\"n6591408481\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Следы от артиллерийских снарядов\",\"x\":-2571.3,\"z\":-165.6,\"material\":\"bronze\",\"startDate\":\"1973\",\"inscription\":\"Это следы одного из 148478 снарядов, выпущенных фашистами по Ленинграду в 1941–1944 гг.\",\"wikidata\":\"Q4423301\",\"wikipedia\":\"ru:Следы от немецких артиллерийских снарядов в Санкт-Петербурге\"},{\"id\":\"n5724704830\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-2934,\"z\":-146.2,\"inscription\":\"В этом доме впервые заседало 6/19 ноября 1905 г. Центральное бюро профессиональных рабочих союзов, об'единение массовых организаций пролетариата Петербурга\"},{\"id\":\"n1612810138\",\"kind\":\"memorial\",\"sub\":\"statue\",\"name\":\"И. Ф. Крузенштерн\",\"x\":-3984.4,\"z\":-241.8,\"material\":\"bronze\",\"subject\":\"Q160888\",\"inscription\":\"Первому русскому плавателю вокруг света адмиралу Ивану Федоровичу Крузенштерну\",\"wikidata\":\"Q66124832\",\"wikipedia\":\"ru:Памятник И. Ф. Крузенштерну\"},{\"id\":\"n8754362391\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-3954.7,\"z\":-305.4,\"inscription\":\"Здесь учились выдающиеся советские флотоводцы: адмигал Головко Арсений Григорьевич с 1925 по 1928 г.г., адмирал Зозуля Федор Владимирович с 1925 по 1928 г.г., адмирал Фокин Виталий Алексеевич с 1924 по 1927 г.г., вице-адмирал Дрозд Валентин Петрович ...\"},{\"id\":\"n8754362392\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-3951.3,\"z\":-307.3,\"inscription\":\"Здесь учились выдающиеся мореплаватели: с 1785 по 1788 г.г. Крузенштерн Иван Федорович, с 1783 по 1788 г.г. Лисянский Юрий Федорович, с 1789 по 1797 г.г. Беллинсгаузен Фаддей Фаддеевич, с 1800 по 1808 г.г. Лазарев Михаил Петрович, ...\"},{\"id\":\"n8754362393\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. В. Верещагину\",\"x\":-3985.7,\"z\":-287.6,\"subject\":\"Q127017\",\"inscription\":\"Здесь учился и в 1860 году окончил полный курс Морского кадетского корпуса Василий Васильевич Верещагин, великий русский художник\"},{\"id\":\"n8754362395\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. И. Ленину\",\"x\":-4005,\"z\":-276.6,\"subject\":\"Q1394\",\"inscription\":\"В этом здании 8 (21) мая 1917 года на общегородском собрании Петроградской партийной организации выступал Владимир Ильич Ленин с докладом об итогах седьмой (Апрельской) Всероссийской конференции РСДРП(б)\"},{\"id\":\"n8754362396\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-4028.9,\"z\":-262.9,\"inscription\":\"Здесь учились видные советские адмиралы: адмирал флота Советского Союза Кузнецов Николай Герасимович с 1922 по 1926 г., адмирал Трибуц Владимир Филиппович с 1922 по 1926 г., адмирал Октябрьский Филипп Сергеевич, адмирал флота Лобов Семен Михайлович\"},{\"id\":\"n8754362397\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-4031.7,\"z\":-261.3,\"inscription\":\"Здесь учились видные советские адмиралы: адмирал Галлер Лев Михайлович с 1902 по 1905 г., адмирал Левченко Гордей Иванович с 1918 по 1922 г., адмирал Алафузов Владимир Антонович с 1921 по 1925 г., адмирал Владимирский Лев Анатольевич с 1921 по 1925 г.\"},{\"id\":\"n8789928134\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Л. Эйлеру\",\"x\":-3883.4,\"z\":-347.2,\"subject\":\"Q7604\",\"inscription\":\"Здесь жил с 1766 по 1783 г. Леонард Эйлер, член Петербургской Академии Наук, крупнейший математик, механик и физик\"},{\"id\":\"n5895117611\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Я. Домбровскому\",\"x\":-3284.7,\"z\":-134.8,\"subject\":\"Q465213\",\"inscription\":\"В этом здании бывшей Академии Генерального штаба в 1859—1861 годах учился польский революционер-демократ Ярослав Домбровский, генерал, главнокомандующий вооруженными силами Парижской коммуны. Погиб в 1871 году в бою с версальцами\"},{\"id\":\"n6423969736\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-3106.7,\"z\":-138.6,\"inscription\":\"В этом здании с 4 по 14 сентября 1941 года формировалась 6-я дивизия Народного ополчения, участвовавшая в обороне Ленинграда\"}]");
